def _fire_and_forget(coro) -> None:
    """Schedule an async coroutine reliably across NiceGUI/asyncio versions."""
    # IMPORTANTE (NiceGUI):
    # Crear tareas "a pelo" (create_task) rompe el contexto de UI y puede provocar
    # errores como: "The current slot cannot be determined...".
    # Mantengo esta función por compatibilidad, pero NO la usamos para timers/notifications.
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        loop = asyncio.get_event_loop()
    loop.create_task(coro)

