# ---------------- DB ----------------
def db():
    conn = sqlite3.connect(DB_PATH)
    conn.execute('PRAGMA foreign_keys = ON;')
    return conn

def init_db():
    with db() as conn:
        conn.execute("""
        CREATE TABLE IF NOT EXISTS proveedores (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            codigo TEXT UNIQUE,
            nombre TEXT,
            estado_actual TEXT,
            debe REAL,
            haber REAL,
            saldo_pendiente REAL,
            empresa TEXT
        );
        """)
        conn.execute("""
        CREATE TABLE IF NOT EXISTS anotaciones (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            proveedor_id INTEGER NOT NULL,
            fecha TEXT NOT NULL,
            tipo TEXT,
            estado TEXT,
            texto TEXT NOT NULL,
            FOREIGN KEY (proveedor_id) REFERENCES proveedores(id) ON DELETE CASCADE
        );
        """)
        conn.execute("""
        CREATE TABLE IF NOT EXISTS adjuntos (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            proveedor_id INTEGER NOT NULL,
            filename TEXT NOT NULL,
            stored_path TEXT NOT NULL,
            uploaded_at TEXT NOT NULL,
            FOREIGN KEY (proveedor_id) REFERENCES proveedores(id) ON DELETE CASCADE
        );
        """)
        conn.execute("""
        CREATE TABLE IF NOT EXISTS eventos (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            ts TEXT NOT NULL,
            accion TEXT NOT NULL,
            proveedor_id INTEGER,
            detalle TEXT,
            actor_id TEXT,
            FOREIGN KEY (proveedor_id) REFERENCES proveedores(id) ON DELETE SET NULL
        );
        """)

        # per-dispositivo: eventos leidos (persistente sin login)
        conn.execute("""
        CREATE TABLE IF NOT EXISTS notif_reads (
            device_id TEXT NOT NULL,
            event_id INTEGER NOT NULL,
            read_at TEXT NOT NULL,
            PRIMARY KEY (device_id, event_id),
            FOREIGN KEY (event_id) REFERENCES eventos(id) ON DELETE CASCADE
        );
        """)
        # migration (safe)
        try:
            conn.execute("ALTER TABLE proveedores ADD COLUMN estado_actual TEXT;")
        except sqlite3.OperationalError:
            pass
        # nuevos campos contables (safe migration)
        for col_sql in [
            "ALTER TABLE proveedores ADD COLUMN debe REAL;",
            "ALTER TABLE proveedores ADD COLUMN haber REAL;",
            "ALTER TABLE proveedores ADD COLUMN saldo_pendiente REAL;",
        ]:
            try:
                conn.execute(col_sql)
            except sqlite3.OperationalError:
                pass

        # empresa (safe migration)
        try:
            conn.execute("ALTER TABLE proveedores ADD COLUMN empresa TEXT;")
        except sqlite3.OperationalError:
            pass
        # set default empresa for existing rows
        try:
            conn.execute("UPDATE proveedores SET empresa=? WHERE empresa IS NULL OR TRIM(COALESCE(empresa,''))=''", (DEFAULT_EMPRESA,))
        except Exception:
            pass

            try:
                conn.execute(col_sql)
            except sqlite3.OperationalError:
                pass

        try:
            conn.execute("ALTER TABLE eventos ADD COLUMN actor_id TEXT;")
        except sqlite3.OperationalError:
            pass
        conn.commit()

def mark_event_read(device_id: str, event_id: int):
    read_at = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    with db() as conn:
        conn.execute(
            "INSERT OR IGNORE INTO notif_reads (device_id, event_id, read_at) VALUES (?, ?, ?)",
            (device_id, event_id, read_at),
        )
        conn.commit()

def unread_events(device_id: str, limit: int = 200):
    """Devuelve eventos NO leidos para este device_id (excluye los hechos por el mismo device)."""
    with db() as conn:
        cur = conn.execute(
            """
            SELECT e.id, e.ts, e.accion, e.proveedor_id, COALESCE(e.detalle,''), COALESCE(e.actor_id,'')
            FROM eventos e
            LEFT JOIN notif_reads r
              ON r.device_id = ? AND r.event_id = e.id
            WHERE r.event_id IS NULL
              AND COALESCE(e.actor_id,'') <> ?
            ORDER BY e.id DESC
            LIMIT ?
            """,
        (empresa_filter, empresa_filter),
            (device_id, device_id, limit),
        )
        return cur.fetchall()

def unread_count(device_id: str) -> int:
    with db() as conn:
        cur = conn.execute(
            """
            SELECT COUNT(*)
            FROM eventos e
            LEFT JOIN notif_reads r
              ON r.device_id = ? AND r.event_id = e.id
            WHERE r.event_id IS NULL
              AND COALESCE(e.actor_id,'') <> ?
            """,
            (device_id, device_id),
        )
        return int(cur.fetchone()[0] or 0)

