def list_proveedores(q: str | None, estado_filter: str | None, empresa_filter: str | None, limit=500):
    q = (q or '').strip()
    with db() as conn:
        where = []
        args = []
        if q:
            where.append("(p.codigo LIKE ? OR p.nombre LIKE ?)")
            like = f"%{q}%"
            args += [like, like]
        if estado_filter is not None:
            if estado_filter == SIN_ESTADO_LABEL:
                where.append("(COALESCE(p.estado_actual,'') = '')")
            else:
                where.append("(COALESCE(p.estado_actual,'') = ?)")
                args.append(estado_filter)
        if empresa_filter is not None:
            where.append('(COALESCE(p.empresa,\'\') = ?)')
            args.append(empresa_filter)
        where_sql = ("WHERE " + " AND ".join(where)) if where else ""
        args.append(limit)

        cur = conn.execute(
            f"""
            SELECT
                p.id,
                COALESCE(p.codigo,''),
                COALESCE(p.nombre,''),
                COALESCE(p.estado_actual,''),
                COALESCE(p.empresa,''),
                COALESCE((SELECT MAX(a.fecha) FROM anotaciones a WHERE a.proveedor_id=p.id), '') AS ultima_fecha
            FROM proveedores p
            {where_sql}
            ORDER BY (ultima_fecha='') ASC, ultima_fecha DESC, p.nombre ASC
            LIMIT ?
            """,
            args,
        )
        return cur.fetchall()

def counts_por_estado(empresa_filter: str | None = None):
    with db() as conn:
        counts = {s: 0 for s in ESTADOS}
        sin_estado = 0
        cur = conn.execute(
            """
            SELECT COALESCE(estado_actual,''), COUNT(*)
            FROM proveedores
            WHERE (? IS NULL OR COALESCE(empresa,'') = ?)
            GROUP BY COALESCE(estado_actual,'')
            """,
            (empresa_filter, empresa_filter),
        )

        total = 0
        for est, n in cur.fetchall():
            total += n
            if est == '':
                sin_estado = n
            elif est in counts:
                counts[est] = n
        return total, sin_estado, counts

def get_adjuntos(pid: int):
    with db() as conn:
        cur = conn.execute(
            """
            SELECT id, filename, stored_path, uploaded_at
            FROM adjuntos
            WHERE proveedor_id=?
            ORDER BY uploaded_at DESC
            """,
            (pid,),
        )
        return cur.fetchall()

def add_adjunto(pid: int, filename: str, content: bytes):
    # store with safe unique name
    safe_name = filename.replace('..', '_').replace('/', '_').replace('\\', '_')
    stamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    stored = ADJ_DIR / f'{pid}_{stamp}_{safe_name}'
    stored.write_bytes(content)
    uploaded_at = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    with db() as conn:
        conn.execute(
            """
            INSERT INTO adjuntos (proveedor_id, filename, stored_path, uploaded_at)
            VALUES (?, ?, ?, ?)
            """,
            (pid, filename, str(stored), uploaded_at),
        )
        conn.commit()
        log_event('adjunto_subido', pid, filename)

def delete_adjunto(adj_id: int):
    with db() as conn:
        cur = conn.execute("SELECT stored_path FROM adjuntos WHERE id=?", (adj_id,))
        row = cur.fetchone()
        if row and row[0]:
            try:
                Path(row[0]).unlink(missing_ok=True)
            except Exception:
                pass
        conn.execute("DELETE FROM adjuntos WHERE id=?", (adj_id,))
        conn.commit()
        log_event('adjunto_borrado', None, f"adj_id={adj_id}")

def days_since(iso_dt: str) -> str:
    if not iso_dt:
        return ''
    try:
        d = datetime.strptime(iso_dt, '%Y-%m-%d %H:%M:%S').date()
        delta = (date.today() - d).days
        return f'{delta}d'
    except Exception:
        return ''

# ---------------- Excel Export ----------------
def _clone_cell_style(src_cell, dst_cell):
    dst_cell.font = src_cell.font.copy()
    dst_cell.fill = src_cell.fill.copy()
    dst_cell.border = src_cell.border.copy()
    dst_cell.alignment = src_cell.alignment.copy()
    dst_cell.number_format = src_cell.number_format
    dst_cell.protection = src_cell.protection.copy()
    dst_cell._style = src_cell._style

def export_excel_to_path(out_path: Path, empresa_filter: str | None = None) -> None:
    if not TEMPLATE_PATH.exists():
        raise FileNotFoundError(f'No encuentro la plantilla: {TEMPLATE_PATH.name}. Ponla en: {TEMPLATE_PATH}')

    wb = openpyxl.load_workbook(TEMPLATE_PATH)
    # For each sheet, capture row2 styles (data row style) before clearing
    row2_style_by_sheet = {}

    for estado, sheet_name in SHEET_BY_ESTADO.items():
        if sheet_name not in wb.sheetnames:
            raise ValueError(f'La plantilla no tiene la hoja: {sheet_name}')
        ws = wb[sheet_name]
        if ws.max_row >= 2:
            row2_style_by_sheet[sheet_name] = [ws.cell(2, c) for c in range(1, ws.max_column + 1)]
        else:
            row2_style_by_sheet[sheet_name] = [ws.cell(1, c) for c in range(1, ws.max_column + 1)]

        # delete existing rows after header
        if ws.max_row >= 2:
            ws.delete_rows(2, ws.max_row - 1)

    # fetch suppliers and their last note
    # We'll export by estado_actual; empty -> SIN ESTADO (we skip because template has no sheet)
    with db() as conn:
        cur = conn.execute("""
        SELECT p.id, COALESCE(p.codigo,''), COALESCE(p.nombre,''), COALESCE(p.estado_actual,''), COALESCE(p.debe,0), COALESCE(p.haber,0), COALESCE(p.saldo_pendiente,0), COALESCE(p.empresa,'')
        FROM proveedores p
        WHERE (? IS NULL OR COALESCE(p.empresa,'') = ?)
        ORDER BY COALESCE(p.estado_actual,''), p.nombre, p.codigo
        """, (empresa_filter, empresa_filter))
        proveedores = cur.fetchall()

        # last note map
        cur2 = conn.execute("""
        SELECT a.proveedor_id, a.fecha, COALESCE(a.tipo,''), COALESCE(a.estado,''), a.texto
        FROM anotaciones a
        INNER JOIN (
            SELECT proveedor_id, MAX(fecha) AS max_fecha
            FROM anotaciones
            GROUP BY proveedor_id
        ) x
        ON a.proveedor_id = x.proveedor_id AND a.fecha = x.max_fecha
        """)
        last_map = {r[0]: (r[1], r[2], r[3], r[4]) for r in cur2.fetchall()}

    # write rows per estado sheet
    for pid, codigo, nombre, estado_actual, debe, haber, saldo_pendiente, empresa in proveedores:
        estado_actual = (estado_actual or '').strip()
        if estado_actual not in SHEET_BY_ESTADO:
            # no sheet for SIN ESTADO in template; ignore
            continue

        sheet_name = SHEET_BY_ESTADO[estado_actual]
        ws = wb[sheet_name]

        row_idx = ws.max_row + 1  # append
        # ensure at least 7 columns as template
        # Fill as per template columns:
        # A Código Pgc, B Titulo cuenta pgc, C Saldo, D Saldo Facturas Pendientes, E Diferencia,
        # F Comentarios Contabilidad, G Comentarios Jose Montenegro
        values = [''] * 7
        values[0] = codigo
        values[1] = nombre

        last = last_map.get(pid)
        if last:
            fecha, tipo, est, texto = last
            # Put a compact summary in comentarios
            values[5] = f'[{fecha}] {tipo} · {est}\n{texto}' if texto else f'[{fecha}] {tipo} · {est}'
        else:
            values[5] = ''

        # Create row
        for c in range(1, 8):
            cell = ws.cell(row_idx, c, values[c - 1])
            # Copy style from saved row2 style if present
            template_cells = row2_style_by_sheet.get(sheet_name)
            if template_cells and len(template_cells) >= c:
                _clone_cell_style(template_cells[c - 1], cell)

    # ---- Extra sheet: Debe/Haber (moderno y directo) ----
    sheet_name = 'DEBE_HABER'
    if sheet_name in wb.sheetnames:
        ws_dh = wb[sheet_name]
        # clear old rows except header
        if ws_dh.max_row >= 2:
            ws_dh.delete_rows(2, ws_dh.max_row - 1)
    else:
        ws_dh = wb.create_sheet(sheet_name)

    headers = ['Empresa','Código', 'Proveedor', 'Estado', 'Debe', 'Haber', 'Saldo pendiente', 'Última fecha', 'Última nota']
    ws_dh.delete_rows(1, ws_dh.max_row)
    ws_dh.append(headers)
    ws_dh.freeze_panes = 'A2'

    # simple header style
    header_font = Font(bold=True)
    for c in range(1, len(headers) + 1):
        cell = ws_dh.cell(1, c)
        cell.font = header_font
        cell.alignment = Alignment(vertical='center')

    # Fill rows
    for pid, codigo, nombre, estado_actual, debe, haber, saldo_pendiente, empresa in proveedores:
        last = last_map.get(pid)
        ultima_fecha = last[0] if last else ''
        ultima_txt = last[3] if last else ''
        ws_dh.append([
            empresa or '',
            codigo,
            nombre,
            estado_actual or '',
            float(debe or 0),
            float(haber or 0),
            float(saldo_pendiente or 0),
            ultima_fecha,
            ultima_txt,
        ])

    # number formats
    for r in range(2, ws_dh.max_row + 1):
        for c in (5, 6, 7):
            ws_dh.cell(r, c).number_format = '#,##0.00'


    wb.save(out_path)

# ---------------- PDF + ZIP Export ----------------
def _safe_fs_name(name: str) -> str:
    name = (name or '').strip()
    if not name:
        return 'proveedor'
    bad = '<>:"/\\|?*'
    for ch in bad:
        name = name.replace(ch, '_')
    name = name.replace('..', '_')
    name = name.strip().strip('.')
    return name[:140] if len(name) > 140 else name

def _format_money(x) -> str:
    try:
        v = float(x or 0)
        # Spanish-style formatting (1.234,56)
        s = f"{v:,.2f}"
        s = s.replace(",", "X").replace(".", ",").replace("X", ".")
        return s
    except Exception:
        return ""

def build_proveedor_pdf(pid: int, out_pdf: Path) -> None:
    prov = get_proveedor(pid)
    if not prov:
        raise ValueError('Proveedor no encontrado')

    # get_proveedor returns: id, codigo, nombre, estado_actual, debe, haber, empresa
    _pid, cod, nom, est_actual, debe, haber, empresa = prov
    saldo = (float(debe or 0) - float(haber or 0))

    notes = listado_anotaciones(pid, limit=1000000)  # all notes

    c = canvas.Canvas(str(out_pdf), pagesize=A4)
    width, height = A4
    left = 18 * mm
    top = height - 18 * mm
    y = top

    def new_page():
        nonlocal y
        c.showPage()
        y = top

    def draw_wrapped(line: str, font='Helvetica', size=10, max_chars=110):
        nonlocal y
        c.setFont(font, size)
        s = (line or '')
        parts = []
        while len(s) > max_chars:
            cut = s.rfind(' ', 0, max_chars)
            if cut == -1:
                cut = max_chars
            parts.append(s[:cut])
            s = s[cut:].lstrip()
        parts.append(s)
        for part in parts:
            if y < 18 * mm:
                new_page()
            c.drawString(left, y, part)
            y -= 5 * mm

    c.setFont('Helvetica-Bold', 16)
    title = f'Proveedor: {cod or "(sin código)"} — {nom or "(sin nombre)"}'
    c.drawString(left, y, title[:95])
    y -= 9 * mm

    draw_wrapped(f'Empresa: {empresa or DEFAULT_EMPRESA}', font='Helvetica', size=11)
    draw_wrapped(f'Estado actual: {est_actual or SIN_ESTADO_LABEL}', font='Helvetica', size=11)
    draw_wrapped(f'Debe: {_format_money(debe)}    Haber: {_format_money(haber)}    Saldo pendiente: {_format_money(saldo)}', font='Helvetica', size=11)
    y -= 2 * mm
    c.setStrokeColorRGB(0.75, 0.75, 0.75)
    c.line(left, y, width - left, y)
    y -= 8 * mm

    draw_wrapped('Histórico de anotaciones', font='Helvetica-Bold', size=12)
    y -= 2 * mm

    if not notes:
        draw_wrapped('— Sin anotaciones —', font='Helvetica', size=10)
    else:
        # oldest -> newest
        for fecha, tipo, est, txt in reversed(notes):
            draw_wrapped(f'[{fecha}]  {tipo or "-"}  ·  {est or "-"}', font='Helvetica-Bold', size=10)
            for para in (txt or '').splitlines() or ['']:
                if para.strip():
                    draw_wrapped(para, font='Helvetica', size=10)
                else:
                    draw_wrapped(' ', font='Helvetica', size=10)
            y -= 2 * mm

    c.save()

def export_zip_pdfs_and_adjuntos(out_zip: Path, empresa_filter: str | None = None) -> None:
    tmp_root = Path(tempfile.mkdtemp(prefix='export_proveedores_'))
    try:
        with db() as conn:
            cur = conn.execute(
                "SELECT id, COALESCE(codigo,''), COALESCE(nombre,''), COALESCE(empresa,'') "
                "FROM proveedores WHERE (? IS NULL OR COALESCE(empresa,'') = ?) "
                "ORDER BY COALESCE(empresa,''), COALESCE(nombre,''), COALESCE(codigo,'')",
                (empresa_filter, empresa_filter),
            )
            proveedores = cur.fetchall()

        for pid, codigo, nombre, empresa in proveedores:
            empresa_name = (empresa or DEFAULT_EMPRESA).strip() or DEFAULT_EMPRESA
            emp_dir = tmp_root / _safe_fs_name(empresa_name)
            emp_dir.mkdir(parents=True, exist_ok=True)

            folder = _safe_fs_name(f"{codigo or 'SIN_CODIGO'} - {nombre or 'SIN_NOMBRE'}")
            prov_dir = emp_dir / folder
            prov_dir.mkdir(parents=True, exist_ok=True)

            pdf_path = prov_dir / "ANOTACIONES.pdf"
            build_proveedor_pdf(pid, pdf_path)

            adjs = get_adjuntos(pid)
            if adjs:
                adj_dir = prov_dir / "ADJUNTOS"
                adj_dir.mkdir(exist_ok=True)
                used = set()
                for _adj_id, filename, stored_path, uploaded_at in adjs:
                    src = Path(stored_path)
                    if not src.exists():
                        continue
                    base = _safe_fs_name(filename) or "adjunto"
                    dst = adj_dir / base
                    k = 1
                    while str(dst).lower() in used or dst.exists():
                        dst = adj_dir / f"{dst.stem} ({k}){dst.suffix}"
                        k += 1
                    used.add(str(dst).lower())
                    try:
                        shutil.copy2(src, dst)
                    except Exception:
                        try:
                            dst.write_bytes(src.read_bytes())
                        except Exception:
                            pass

        with zipfile.ZipFile(out_zip, 'w', compression=zipfile.ZIP_DEFLATED) as zf:
            for p in tmp_root.rglob('*'):
                if p.is_dir():
                    continue
                zf.write(p, arcname=str(p.relative_to(tmp_root)))
    finally:
        shutil.rmtree(tmp_root, ignore_errors=True)


